/**
 * Playthrough suite: the whole loop, from a fresh save to a mid-game position.
 *
 * The unit suite pins the rules. This file pins the EXPERIENCE — that a player
 * can actually get from 涿郡 184 to 新野 207 without the engine wedging, that
 * the three counters behave like the historical record says they do, and that a
 * "扮演" run (departing from history) stays playable rather than collapsing.
 *
 * It runs against the real act table and the real save layer, in a temp dir, so
 * it exercises the same paths the plugin does minus the model.
 *
 *   node --test test/*.test.mjs
 */
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { mkdtempSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { readFileSync } from 'node:fs'

import { createSave, save, load } from '../engine/state.js'
import { seedFactions, indexActs, currentScene, chooseBranch, attemptScene, advanceWorld, nextCursor } from '../engine/acts.js'
import { buildDigest, renderDigest } from '../engine/digest.js'
import { describe as describeDrift, DRIFT_MAX } from '../engine/destiny.js'

const ACTS = indexActs(JSON.parse(readFileSync(new URL('../data/acts.json', import.meta.url), 'utf8')))

/** Play one scene to completion using whichever path the scene kind implies. */
function playScene(state, optionId) {
  const { act, scene } = currentScene(state, ACTS)
  if (scene === null) {
    return { state, skipped: true }
  }
  let resolved
  if (scene.kind === 'moral') {
    const chosen = optionId ?? scene.options.find((option) => option.historical === true)?.id ?? scene.options[0].id
    resolved = chooseBranch(state, act, scene, chosen)
    return { state: resolved.state, resolved, scene }
  }
  resolved = attemptScene(state, act, scene, {})
  return { state: resolved.state, resolved, scene }
}

test('playthrough: a fresh save can play the opening scene', () => {
  let state = seedFactions(createSave('opening'))
  const { act, scene } = currentScene(state, ACTS)
  assert.equal(act.id, 'zhuojun')
  assert.equal(scene.kind, 'moral')
  const played = playScene(state, 'say_it')
  assert.equal(played.state.player.counters.fame, 8)
})

test('playthrough: playing the historical path keeps drift at zero', () => {
  let state = seedFactions(createSave('historical'))
  const act = ACTS.get('zhuojun')
  for (let index = 0; index < act.scenes.length; index += 1) {
    const played = playScene(state, null)
    state = played.state
  }
  assert.equal(state.drift, 0, 'following the record is never a departure')
  assert.equal(state.counters.deviations, 0)
})

test('playthrough: playing against history accumulates drift but never blocks', () => {
  let state = seedFactions(createSave('deviant'))
  const act = ACTS.get('zhuojun')
  for (let index = 0; index < act.scenes.length; index += 1) {
    const { act: current, scene } = currentScene(state, ACTS)
    if (scene === null) break
    if (scene.kind === 'moral') {
      const departure = scene.options.find((option) => option.historical !== true)
      const played = playScene(state, departure?.id)
      state = played.state
    } else {
      const played = playScene(state, null)
      state = played.state
    }
  }
  assert.ok(state.drift > 0, 'deviations must be priced')
  assert.ok(state.drift <= DRIFT_MAX)
  // The game must still be playable at maximum drift: a digest still builds,
  // and the world mood is still a phrase rather than an error.
  const digest = buildDigest(state, {})
  assert.ok(digest.world.mood.length > 0)
})

test('playthrough: the whole act table can be walked without wedging', () => {
  let state = seedFactions(createSave('walk'))
  let guard = 0
  while (state.act !== 'end' && guard < 200) {
    guard += 1
    const { scene } = currentScene(state, ACTS)
    if (scene === null) {
      state = nextCursor(state, ACTS)
      continue
    }
    const played = playScene(state, null)
    state = played.state
    state = nextCursor(state, ACTS)
    // Keep the clock in step with the act the player has reached, the way the
    // plugin's advance tool would.
    const act = ACTS.get(state.act)
    if (act !== undefined && Number.isFinite(act.ageFrom) && state.age < act.ageFrom) {
      const needed = act.ageFrom - state.age
      state = advanceWorld(state, Math.max(1, needed * 4)).state
    }
  }
  assert.ok(guard < 200, 'the walk must terminate')
  assert.equal(state.act, 'end')
  assert.ok(state.log.length > 0)
  assert.ok(state.counters.choicesMade > 0)
})

test('playthrough: the save survives a round-trip mid-run', async () => {
  const dir = mkdtempSync(join(tmpdir(), 'sanguo-play-'))
  let state = seedFactions(createSave('persist'))
  state = playScene(state, 'say_it').state
  await save(dir, state)
  const loaded = await load(dir)
  assert.equal(loaded.player.counters.fame, state.player.counters.fame)
  assert.equal(loaded.act, state.act)
  assert.equal(loaded.scene, state.scene)
})

test('playthrough: fame compounds across acts the way the record says', () => {
  // Start, then take the three highest-fame historical branches available in
  // the opening act. Fame must be monotonically non-decreasing.
  let state = seedFactions(createSave('compound'))
  const before = state.player.counters.fame
  for (let index = 0; index < 4; index += 1) {
    const { scene } = currentScene(state, ACTS)
    if (scene === null) break
    const played = playScene(state, null)
    state = played.state
  }
  assert.ok(state.player.counters.fame >= before)
  assert.ok(state.player.counters.fame <= 100)
})

test('playthrough: the world moves even when the player does nothing', () => {
  const state = { ...seedFactions(createSave('idle')), clock: { year: 184, turn: 0 }, age: 23 }
  const advanced = advanceWorld(state, 8)
  const caocaoBefore = state.factions.caocao.power
  const caocaoAfter = advanced.state.factions.caocao.power
  assert.notEqual(caocaoAfter, caocaoBefore, 'Cao Cao does not wait for the player')
  assert.equal(advanced.state.clock.year, 186)
})

test('playthrough: two years of idling costs nothing in drift', () => {
  const state = { ...seedFactions(createSave('idle-drift')), clock: { year: 184, turn: 0 }, age: 23 }
  const advanced = advanceWorld(state, 8)
  assert.equal(advanced.state.drift, 0)
})

test('playthrough: a digest of a mid-game save stays readable and small', () => {
  let state = seedFactions(createSave('digest-size'))
  for (let index = 0; index < 6; index += 1) {
    const { scene } = currentScene(state, ACTS)
    if (scene === null) break
    state = playScene(state, null).state
  }
  const digest = buildDigest(state, {})
  const text = renderDigest(digest)
  assert.ok(text.length > 0)
  assert.ok(text.length < 2000, `digest text should stay small, got ${text.length}`)
  assert.ok(JSON.stringify(digest).length < 8000, 'structured digest should stay small')
})

test('playthrough: the opening of 扮演 mode is a real choice, not a warning', () => {
  // Every moral node must offer at least one non-historical branch, or the
  // "扮演" promise is a lie at that node.
  for (const [id, act] of ACTS) {
    for (const scene of act.scenes) {
      if (scene.kind !== 'moral') continue
      const departures = scene.options.filter((option) => option.historical !== true)
      assert.ok(departures.length >= 1, `${id}/${scene.id} offers no departure`)
    }
  }
})

test('playthrough: drift describes a mood at every legal value', () => {
  for (let drift = 0; drift <= DRIFT_MAX; drift += 5) {
    const phrase = describeDrift(drift)
    assert.ok(typeof phrase === 'string' && phrase.length > 0)
  }
})
